// Author: MiYu. Original local multiplayer browsing screen and live LAN discovery results.
#include "lan_browser.h"
#include <algorithm>
#include <cmath>

namespace war3 {
namespace {
bool hit(GlueScreen::Rect r,float x,float y){return x>=r.x && y>=r.y && x<r.x+r.w && y<r.y+r.h;}
bool click(GlueScreen::Rect r,const UiInput& input){return input.pressed && hit(r,input.x,input.y) && hit(r,input.startX,input.startY);}
std::string key(const LanGame& game){return game.address+":"+std::to_string(game.port)+":"+std::to_string(game.hostCounter)+":"+std::to_string(game.entryKey);}
std::string display(std::string_view input){try{return utf8(wide(input));}catch(const std::exception&){if(input.empty())return {};int size=MultiByteToWideChar(CP_ACP,0,input.data(),int(input.size()),nullptr,0);if(size<=0)return "?";std::wstring text(size,L'\0');MultiByteToWideChar(CP_ACP,0,input.data(),int(input.size()),text.data(),size);return utf8(text);}}
}
LanBrowser::LanBrowser(Archives& archives,Images& images,Renderer& renderer,Text& text,Log& log) : screen_(archives,images,renderer,text,"UI\\FrameDef\\Glue\\LocalMultiplayerJoin.fdf","LocalMultiplayerJoin"),archives_(archives),images_(images),renderer_(renderer),text_(text),log_(log) {screen_.focusEnabled(false);start();}
void LanBrowser::enableMatchHandoff(){matchHandoffEnabled_=true;if(lobby_)lobby_->enableMatchHandoff();if(host_)host_->enableMatchHandoff();}
std::optional<LanLobbyHandoff> LanBrowser::takeHandoff(){if(!lobby_)return {};auto handoff=lobby_->takeHandoff();if(handoff)lobby_.reset();return handoff;}
std::optional<LanHostHandoff> LanBrowser::takeHostHandoff(){if(!host_)return {};auto handoff=host_->takeHandoff();if(handoff)host_.reset();return handoff;}
std::string LanBrowser::pollMinimized(){if(host_)return host_->pollMinimized();if(lobby_)return lobby_->pollMinimized();if(discovery_)try{discovery_->poll();auto now=GetTickCount64();if(now>=nextSearch_){discovery_->refresh();nextSearch_=now+4000;}}catch(const std::exception& e){discovery_.reset();error_="局域网搜索中断。按 F5 重试。";log_.write(std::string("lan_discovery_failed=")+e.what());}return {};}
void LanBrowser::start(){try{auto next=std::make_unique<LanDiscovery>();next->refresh();discovery_=std::move(next);nextSearch_=GetTickCount64()+4000;error_.clear();}catch(const std::exception& e){discovery_.reset();error_="无法搜索局域网游戏。按 F5 重试。";log_.write(std::string("lan_discovery_failed=")+e.what());}}
std::string LanBrowser::draw(const UiInput& input,std::wstring_view characters){
    if(host_){auto action=host_->draw(input,characters);if(action=="CancelButton"){host_.reset();start();}else if(action=="PrepareGame")return action;return {};}if(lobby_){auto action=lobby_->draw(input,characters);if(action=="CancelButton"){lobby_.reset();start();}else if(action=="PrepareGame")return action;return {};}if(input.key==VK_ESCAPE)return "CancelButton";if(input.key==VK_F5){discovery_.reset();start();}if(discovery_){try{discovery_->poll();auto now=GetTickCount64();if(now>=nextSearch_){discovery_->refresh();nextSearch_=now+4000;}}catch(const std::exception& e){discovery_.reset();error_="局域网搜索中断。按 F5 重试。";log_.write(std::string("lan_discovery_failed=")+e.what());}}
    std::vector<LanGame> filtered;static const std::vector<LanGame> empty;if(discovery_ && matchHandoffEnabled_){for(auto& game:discovery_->games())if(game.name.starts_with(experimentalLanPrefix))filtered.push_back(game);}auto& games=discovery_?(matchHandoffEnabled_?filtered:discovery_->games()):empty;auto found=std::find_if(games.begin(),games.end(),[&](auto& item){return key(item)==selection_;});if(found==games.end()){selection_.clear();selected_=0;}else selected_=size_t(found-games.begin());auto list=screen_.bounds("GameListContainer"),name=screen_.bounds("PlayerNameEditBox");constexpr float step=.01875f;auto rows=std::max(1u,unsigned(std::max(0.f,list.h-.008f)/step));auto maximum=games.size()>rows?games.size()-rows:0;scroll_=std::min(scroll_,maximum);
    auto choose=[&](size_t index){if(index>=games.size())return;selected_=index;selection_=key(games[index]);if(index<scroll_)scroll_=index;if(index>=scroll_+rows)scroll_=index-rows+1;};
    if(click(name,input))nameFocus_=true;if(click(list,input))nameFocus_=false;if(input.key==VK_TAB)nameFocus_=!nameFocus_;if(nameFocus_){for(wchar_t c:characters){if(c==8){highSurrogate_=0;if(!playerName_.empty()){if(playerName_.back()>=0xdc00 && playerName_.back()<=0xdfff && playerName_.size()>1)playerName_.pop_back();playerName_.pop_back();}}else if(c>=0xd800 && c<=0xdbff)highSurrogate_=c;else if(c>=0xdc00 && c<=0xdfff){if(highSurrogate_ && playerName_.size()+2<=31){playerName_+=highSurrogate_;playerName_+=c;}highSurrogate_=0;}else {highSurrogate_=0;if(c>=32 && playerName_.size()<31)playerName_+=c;}}}else if(!games.empty()){if(input.key==VK_UP)choose(selected_?selected_-1:0);if(input.key==VK_DOWN)choose(std::min(selected_+1,games.size()-1));if(input.key==VK_HOME)choose(0);if(input.key==VK_END)choose(games.size()-1);if(input.key==VK_PRIOR)choose(selected_>=rows?selected_-rows:0);if(input.key==VK_NEXT)choose(std::min(selected_+rows,games.size()-1));}
    bool activate=false;if(hit(list,input.x,input.y) && input.wheel)scroll_=size_t(std::clamp<long long>(static_cast<long long>(scroll_)-input.wheel*3ll,0,static_cast<long long>(maximum)));for(size_t row=0;row<rows && scroll_+row<games.size();++row){auto area=GlueScreen::Rect{list.x+.004f,list.y+.004f+float(row)*step,list.w-.0245f,step};if(click(area,input)){nameFocus_=false;choose(scroll_+row);activate=input.doubleClick;break;}}
    auto track=GlueScreen::Rect{list.x+list.w-.0205f,list.y+.004f,.0165f,list.h-.008f},up=GlueScreen::Rect{track.x,track.y,track.w,.015f},down=GlueScreen::Rect{track.x,track.y+track.h-.015f,track.w,.015f};float travel=track.h-.04f;if(click(up,input) && scroll_)--scroll_;if(click(down,input) && scroll_<maximum)++scroll_;auto trough=GlueScreen::Rect{track.x,track.y+.015f,track.w,track.h-.03f};if(maximum && travel>0 && input.down && hit(trough,input.startX,input.startY))scroll_=size_t(std::clamp((input.y-trough.y-.005f)/travel,0.f,1.f)*float(maximum)+.5f);
    if(selection_.empty()){screen_.setText("GameCreatorValue","");screen_.setText("GameSpeedValue","");}else{screen_.setText("GameCreatorValue",display(games[selected_].hostName));screen_.setText("GameSpeedValue","");}auto controls=input;if(nameFocus_)controls.key=0;std::set<std::string> enabled{"CancelButton"};if(!playerName_.empty())enabled.insert("CreateButton");if(!selection_.empty() && games[selected_].slotsAvailable && !playerName_.empty())enabled.insert("JoinButton");auto action=screen_.draw("LocalMultiplayerJoin",controls,enabled,true);if(!nameFocus_ && input.key==VK_RETURN && enabled.contains("JoinButton"))activate=true;if(action=="JoinButton")activate=true;screen_.backdropAt("StandardEditBoxBackdropTemplate",name);screen_.textAt("StandardEditBoxTextTemplate",utf8(playerName_),{name.x+.005f,name.y,name.w-.01f,name.h},true,false,true,.012f);screen_.backdropAt("StandardEditBoxBackdropTemplate",list);
    float scale=std::min(renderer_.width()/.8f,renderer_.height()/.6f),left=(renderer_.width()-.8f*scale)/2,top=(renderer_.height()-.6f*scale)/2;auto quad=[&](GlueScreen::Rect r,DWORD color){renderer_.rect(left+r.x*scale,top+r.y*scale,r.w*scale,r.h*scale,color);};if(nameFocus_){quad({name.x,name.y,name.w,.001f},0xffffcc55);quad({name.x,name.y+name.h-.001f,name.w,.001f},0xffffcc55);}
    for(size_t row=0;row<rows && scroll_+row<games.size();++row){size_t index=scroll_+row;auto area=GlueScreen::Rect{list.x+.004f,list.y+.004f+float(row)*step,list.w-.0245f,step};if(!selection_.empty() && index==selected_)quad(area,0x9f344b6b);auto label=display(games[index].name)+"  (空位 "+std::to_string(games[index].slotsAvailable)+" / "+std::to_string(games[index].slotsTotal)+")";screen_.textAt("StandardInfoTextTemplate",label,area,true,!selection_.empty() && index==selected_,true,.013f);}
    screen_.backdropAt("StandardScrollBarBackdrop",track);screen_.backdropAt("StandardScrollBarIncButtonBackdrop",up);screen_.backdropAt("StandardScrollBarDecButtonBackdrop",down);screen_.backdropAt("StandardThumbButtonBackdrop",{track.x+.00325f,track.y+.015f+(maximum?float(scroll_)/float(maximum)*travel:0),.01f,.01f});
    if(!selection_.empty())screen_.textAt("StandardInfoTextTemplate",display(games[selected_].mapPath),screen_.bounds("MapInfoPaneContainer"),true,false,true,.011f);else screen_.textAt("StandardInfoTextTemplate",discovery_?"正在搜索局域网游戏…":"",{list.x+.01f,list.y+.01f,list.w-.03f,.025f},true,false,true,.011f);if(!error_.empty())screen_.textAt("StandardInfoTextTemplate",error_,{.025f,.46f,.42f,.025f},true,false,true,.011f);screen_.overlay();if(action=="CreateButton" && enabled.contains("CreateButton")){try{auto hostPlayerName=utf8(playerName_);if(hostPlayerName.empty() || hostPlayerName.size()>15)error_="玩家名需为 1–15 字节。";else{host_=std::make_unique<LanHostUi>(archives_,images_,renderer_,text_,log_,std::move(hostPlayerName));if(matchHandoffEnabled_)host_->enableMatchHandoff();discovery_.reset();error_.clear();}}catch(const std::exception& e){error_="无法打开建房界面。";log_.write(std::string("lan_host_ui_failed=")+e.what());}}if(activate && enabled.contains("JoinButton")){try{auto playerName=utf8(playerName_);if(playerName.empty() || playerName.size()>15)error_="玩家名需为 1–15 字节。";else{lobby_=std::make_unique<LanLobby>(archives_,images_,renderer_,text_,games[selected_],std::move(playerName));if(matchHandoffEnabled_)lobby_->enableMatchHandoff();error_.clear();}}catch(const std::exception& e){error_="无法连接所选房间。";log_.write(std::string("lan_join_failed=")+e.what());}}return action=="CancelButton"?action:std::string{};
}
}
